#!/usr/bin/env bash
# Tests e2e/incident-card.mjs with literal fixtures, written here by hand:
# - the status items in the markup of status src/render.ts:648-728 @ 8b6d431 (manualHead,
#   manualComponents, manualUpdate, renderManualIncidents, renderResolvedManualIncidents);
# - the console previews in the markup of section 9 of spec #569 (data-part elements, the
#   message in a <p>).
# The expected JSON is a literal too; nothing is generated by the extractor or a renderer.
# Usage: bash e2e/incident-card.test.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
fails=0
check() { # check <name> <want> <got>
  if [[ "$3" == "$2" ]]; then
    echo "ok: $1"
  else
    echo "FAIL: $1"
    printf '  want: %s\n  got:  %s\n' "$2" "$3"
    fails=$((fails + 1))
  fi
}
card() { node e2e/incident-card.mjs "$@"; }

nl=$'\n'
# The step 2 input of the scenario: title E2E <script>alert(1)</script> Ünï 😀, impact major,
# component web (name Web), status investigating, message "Line one" LF "Line <b>two</b>".
open_json='{"impact":"Impact: major","status":"Status: investigating","title":"E2E <script>alert(1)</script> Ünï 😀","affects":"Affects: Web","updates":[{"status":"investigating","message":"Line one\nLine <b>two</b>"}]}'

# Status page: renderManualIncidents with one open incident (id 7) and another one (id 8).
cat >"$tmp/status-open.html" <<'EOF'
<h2>Ongoing incidents</h2><ul class="manual-incidents"><li class="manual-incident impact-minor" data-key="manual:8" aria-labelledby="manual-name-8"><div class="manual-head"><span class="manual-impact">Impact: minor</span><span class="manual-status">Status: identified</span><span class="name" id="manual-name-8">Other</span></div><ul class="manual-updates"><li class="manual-update" data-key="manual-update:8:1700000000000"><span class="manual-update-status">identified</span> <time class="time" datetime="2023-11-14T22:13:20Z" data-exact="x" title="x" aria-label="x">1 h ago</time><p class="manual-message">Other message</p></li></ul></li><li class="manual-incident impact-major" data-key="manual:7" aria-labelledby="manual-name-7"><div class="manual-head"><span class="manual-impact">Impact: major</span><span class="manual-status">Status: investigating</span><span class="name" id="manual-name-7">E2E &lt;script&gt;alert(1)&lt;/script&gt; Ünï 😀</span><span class="manual-components">Affects: Web</span></div><ul class="manual-updates"><li class="manual-update" data-key="manual-update:7:1700000001000"><span class="manual-update-status">investigating</span> <time class="time" datetime="2023-11-14T22:13:21Z" data-exact="2023-11-14 22:13:21 UTC" title="2023-11-14 22:13:21 UTC" aria-label="2023-11-14 22:13:21 UTC">just now</time><p class="manual-message">Line one
Line &lt;b&gt;two&lt;/b&gt;</p></li></ul></li></ul>
EOF
# Console preview (section 9), open, for the same input.
cat >"$tmp/preview-open.html" <<'EOF'
<form method="post" action="/incidents/new"></form>
<section aria-labelledby="preview-heading">
<h2 id="preview-heading">Status page preview</h2>
<div class="incident-preview" data-preview="open">
<p><span data-part="impact">Impact: major</span> <span data-part="status">Status: investigating</span></p>
<h3 data-part="title">E2E &lt;script&gt;alert(1)&lt;/script&gt; Ünï 😀</h3>
<p data-part="affects">Affects: Web</p>
<div class="preview-updates"><div data-part="update"><span data-part="update-status">investigating</span> <span data-part="time">when published</span><p class="preview-message" data-part="message">Line one
Line &lt;b&gt;two&lt;/b&gt;</p></div></div>
</div>
</section>
EOF
check "status open card" "$open_json" "$(card "$tmp/status-open.html" status 7)"
check "preview open card" "$open_json" "$(card "$tmp/preview-open.html" preview)"
check "the message keeps the LF" "Line one${nl}Line <b>two</b>" \
  "$(card "$tmp/preview-open.html" preview | node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(0,"utf8")).updates[0].message)')"

# Resolved: all 4 updates oldest first. A leading LF in a <p> message is kept.
resolved_json='{"impact":"Impact: major","status":"Status: resolved","title":"E2E <script>alert(1)</script> Ünï 😀","affects":"Affects: Web","updates":[{"status":"investigating","message":"Line one\nLine <b>two</b>"},{"status":"identified","message":"Cause &lt; found."},{"status":"monitoring","message":"\nFix deployed."},{"status":"resolved","message":"Resolved."}]}'
cat >"$tmp/status-resolved.html" <<'EOF'
<h3>Manual incidents resolved in the last 14 days</h3><ul class="manual-incidents"><li class="manual-incident resolved impact-major" data-key="manual:7" aria-labelledby="manual-name-7"><div class="manual-head"><span class="manual-impact">Impact: major</span><span class="manual-status">Status: resolved</span><span class="name" id="manual-name-7">E2E &lt;script&gt;alert(1)&lt;/script&gt; Ünï 😀</span><span class="manual-components">Affects: Web</span></div><ul class="manual-updates"><li class="manual-update" data-key="manual-update:7:1"><span class="manual-update-status">investigating</span> <time class="time" datetime="a">1 h ago</time><p class="manual-message">Line one
Line &lt;b&gt;two&lt;/b&gt;</p></li><li class="manual-update" data-key="manual-update:7:2"><span class="manual-update-status">identified</span> <time class="time" datetime="b">50 min ago</time><p class="manual-message">Cause &amp;lt; found.</p></li><li class="manual-update" data-key="manual-update:7:3"><span class="manual-update-status">monitoring</span> <time class="time" datetime="c">40 min ago</time><p class="manual-message">
Fix deployed.</p></li><li class="manual-update" data-key="manual-update:7:4"><span class="manual-update-status">resolved</span> <time class="time" datetime="d">just now</time><p class="manual-message">Resolved.</p></li></ul></li></ul>
EOF
cat >"$tmp/preview-resolved.html" <<'EOF'
<section aria-labelledby="preview-heading">
<h2 id="preview-heading">Status page preview</h2>
<div class="incident-preview" data-preview="resolved">
<p><span data-part="impact">Impact: major</span> <span data-part="status">Status: resolved</span></p>
<h3 data-part="title">E2E &lt;script&gt;alert(1)&lt;/script&gt; Ünï 😀</h3>
<p data-part="affects">Affects: Web</p>
<div class="preview-updates"><div data-part="update"><span data-part="update-status">investigating</span> <span data-part="time">2026-11-07 10:00 UTC</span><p class="preview-message" data-part="message">Line one
Line &lt;b&gt;two&lt;/b&gt;</p></div><div data-part="update"><span data-part="update-status">identified</span> <span data-part="time">2026-11-07 10:01 UTC</span><p class="preview-message" data-part="message">Cause &amp;lt; found.</p></div><div data-part="update"><span data-part="update-status">monitoring</span> <span data-part="time">2026-11-07 10:02 UTC</span><p class="preview-message" data-part="message">
Fix deployed.</p></div><div data-part="update"><span data-part="update-status">resolved</span> <span data-part="time">when published</span><p class="preview-message" data-part="message">Resolved.</p></div></div>
</div>
</section>
EOF
check "status resolved card, 4 updates in order" "$resolved_json" "$(card "$tmp/status-resolved.html" status 7)"
check "preview resolved card, 4 updates in order" "$resolved_json" "$(card "$tmp/preview-resolved.html" preview)"

# No component: the status page omits manual-components; the preview hides affects.
none_json='{"impact":"Impact: none","status":"Status: monitoring","title":"Plain","affects":null,"updates":[{"status":"monitoring","message":"m"}]}'
cat >"$tmp/status-none.html" <<'EOF'
<ul class="manual-incidents"><li class="manual-incident impact-none" data-key="manual:3" aria-labelledby="manual-name-3"><div class="manual-head"><span class="manual-impact">Impact: none</span><span class="manual-status">Status: monitoring</span><span class="name" id="manual-name-3">Plain</span></div><ul class="manual-updates"><li class="manual-update" data-key="manual-update:3:1"><span class="manual-update-status">monitoring</span> <time class="time">now</time><p class="manual-message">m</p></li></ul></li></ul>
EOF
cat >"$tmp/preview-none.html" <<'EOF'
<div class="incident-preview" data-preview="open">
<p><span data-part="impact"> Impact: none </span> <span data-part="status">Status: monitoring</span></p>
<h3 data-part="title">Plain</h3>
<p data-part="affects" hidden>Affects: </p>
<div class="preview-updates"><div data-part="update"><span data-part="update-status">monitoring</span> <span data-part="time">when published</span><p class="preview-message" data-part="message">m</p></div></div>
</div>
EOF
check "status without components: affects null" "$none_json" "$(card "$tmp/status-none.html" status 3)"
check "preview with hidden affects: affects null, head trimmed" "$none_json" "$(card "$tmp/preview-none.html" preview)"

# Missing item or preview: exit 1. manual:7 does not select manual:70.
set +e
card "$tmp/status-open.html" status 70 >/dev/null 2>&1
check "missing status item exits 1" 1 "$?"
card "$tmp/status-none.html" preview >/dev/null 2>&1
check "missing preview exits 1" 1 "$?"
card "$tmp/status-open.html" status x >/dev/null 2>&1
check "bad id exits 2" 2 "$?"
set -e

((fails == 0)) || { echo "FAIL: $fails incident-card checks" >&2; exit 1; }
echo "ok: incident-card"
